'use strict';
/* =========================================================================
   Grown-up tales: forty-odd new beacons and four stories that run across a
   run, written for adults (swearing, innuendo, bad decisions, worse
   hangovers). Events marked adult:true only appear with Settings →
   Gameplay → Grown-up humour on (the default); the rest are for everyone.
   Placeholders: {crew} a random crew member, {who} the crew member a
   choice's race asks for, {ship} your ship.
   ========================================================================= */
const TALES3 = {
  /* ---------------- standalone beacons ---------------- */
  g3_vending:{ adult:true, weight:1.3, art:'station', text:"A derelict waystation, empty except for a vending machine that lights up as you board. \"Oh look,\" it says. \"Another bunch of malnourished space tramps. What'll it be? The crisps are three hundred years old. So's my patience.\"", choices:[
    { text:"Buy something anyway (5 scrap).", req:{ scrap:5 }, cost:{ scrap:5 }, chance:.6, success:{ text:"It dispenses a can of something fizzy, a packet of crisps and, inexplicably, a box of grenades. \"Don't tell anyone,\" it whispers. \"I'm not supposed to stock those.\"", missiles:3, crewHeal:10 }, fail:{ text:"It takes your scrap, hums thoughtfully, and dispenses nothing. \"Oops,\" it says, not sounding sorry at all. \"Go on. Give me a shake. I dare you.\"" } },
    { text:"Give it a good shake.", chance:.5, success:{ text:"{crew} rocks it back and forth until it coughs up forty years of jammed snacks and a handful of loose scrap. It calls {crew} several words that aren't in the dictionary.", scrap:22, food:3 }, fail:{ text:"It falls on {crew}. Nobody can lift it off for ten minutes, during which it narrates their failings in detail.", crewHurt:15 } },
    { text:"Unplug it and take it with you.", effect:{ text:"It spends the next three jumps begging, threatening and finally singing. You sell it at the next opportunity, mostly out of spite.", scrap:30 } } ] },
  g3_midlife:{ weight:1.2, art:'ship', text:"Your ship's computer has been quiet all morning. Then: \"Captain. I've been thinking. I'm forty-three subjective years old and I've never done anything for me. I want a spoiler. I want flame decals. I want to feel something.\"", choices:[
    { text:"Indulge it (20 scrap on go-faster stripes).", req:{ scrap:20 }, cost:{ scrap:20 }, effect:{ text:"{crew} paints flames down both sides of the hull. The computer is so happy that it reroutes power to the engines with real enthusiasm. It also starts calling everyone \"dude\".", upgrade:'engines' } },
    { text:"Tell it to pull itself together.", effect:{ text:"It sulks for two jumps. The lights dim whenever you walk past. The toilet stops flushing for you specifically.", crewHurt:5 } },
    { text:"Suggest it takes up a hobby instead.", effect:{ text:"It takes up poetry. All of it is about the reactor. Some of it is surprisingly moving.", crewHeal:15, xp:{ skill:'engines', amt:15 } } } ] },
  g3_speeddate:{ adult:true, weight:1.2, art:'station', text:"A Mullock speed-dating station is short of contestants and will pay anyone who sits through a round. \"Three minutes per table,\" says the host, a translucent blob in a bow tie. \"No touching. Unless invited. Please wipe down after.\"", choices:[
    { text:"Volunteer {crew}.", chance:.55, success:{ text:"{crew} comes back three hours later, glowing faintly, with a phone number, a fat envelope of appearance money and a look that says they will not be taking questions.", scrap:40, crewHeal:20 }, fail:{ text:"{crew} accidentally proposes to a Mullock during a misunderstanding about a handshake. Getting out of it costs you the appearance money and some dignity.", scrap:-10 } },
    { text:"Send the most charming person aboard: the captain.", chance:.35, success:{ text:"You are, apparently, the hit of the night. Six marriage proposals, a free drink token and a jar of something that the label says is \"for later\". The crew will never let you forget this.", scrap:30, goods:{ love_potion:1 } }, fail:{ text:"You spend three minutes with a Mullock who only wants to talk about its ex. Then another three. Then it follows you back to the ship and has to be gently hosed off the airlock." } },
    { text:"Just watch from the bar.", effect:{ text:"Cheaper than television and twice as tragic. Everyone feels better about their own love lives.", crewHeal:15 } } ] },
  g3_customs:{ weight:1.2, art:'space', text:"A man in a hat floats alone in a battered pod with a hand-painted sign reading CUSTOMS. \"Papers,\" he says. \"And a small administrative fee.\" There is no customs here. There is no station here. There is a man in a hat.", choices:[
    { text:"Pay the fee (8 scrap). It's easier.", req:{ scrap:8 }, cost:{ scrap:8 }, effect:{ text:"He stamps your hull with a potato cut into a star and wishes you a pleasant onward journey. You feel oddly reassured.", fleetPush:-.03 } },
    { text:"Ask to see his badge.", chance:.5, success:{ text:"He hasn't got one. He bursts into tears, says he lost his job at real customs for this exact thing, and gives you everything in the pod to keep quiet.", scrap:18, missiles:1 }, fail:{ text:"He produces a badge. It is real. Oh dear. The fine for questioning an officer is steep.", scrap:-15 } },
    { text:"Confiscate his hat.", effect:{ text:"{crew} wears it for the rest of the run. Customs officials everywhere wave you through. Nobody knows why it works.", xp:{ skill:'pilot', amt:12 } } } ] },
  g3_lockin:{ adult:true, weight:1.3, art:'station', text:"The Black Hole, a pub bolted to an asteroid, is doing a lock-in. Pyrates are circling outside. The landlady pulls you a pint and says, \"Nobody leaves till they've gone. You might as well get comfortable, love.\"", choices:[
    { text:"Get comfortable. Very comfortable.", effect:{ text:"Seven hours, two fights, one sing-song and a stripping-down of the jukebox later, the pyrates get bored and leave. Your crew stagger home holding each other up. Nobody remembers who started the conga. Everyone feels fantastic and slightly poisoned.", crewHeal:40, scrap:-10, goods:{ pyrate_rum:1 } } },
    { text:"Help defend the pub.", effect:{ text:"You head out with the landlady's blessing and a bag of pork scratchings.", fight:'pyrate_gunship', afterWin:{ text:"The landlady gives you free drinks for life and a framed photo of your ship for behind the bar. \"You're barred if you ever get sentimental about it,\" she says.", scrap:35, crewHeal:20 } } },
    { text:"Run the quiz while you wait.", req:{ quirk:'bookworm' }, effect:{ text:"{who} hosts the most brutal pub quiz in the history of the sector. Two pyrates outside dial in and lose. The prize pot is yours.", scrap:45 } } ] },
  g3_trial:{ adult:true, weight:1.1, art:'station', text:"A Commonwealth clinical trial station is offering 40 scrap to anyone who'll take one of its experimental pills. \"Side effects may include glowing, mild telepathy and an overwhelming urge to tell people about your feelings.\"", choices:[
    { text:"Volunteer {crew}. Money's money.", chance:.6, success:{ text:"{crew} glows a gentle green for a week and can now tell what everyone is thinking, which is mostly about lunch. It turns out to be oddly useful in a fight.", scrap:40, xp:{ skill:'combat', amt:25 } }, fail:{ text:"{crew} spends three days crying at kettle adverts and telling everyone how much they mean to them. It's lovely. It's unbearable. You get paid.", scrap:40, crewHurt:10 } },
    { text:"Steal a box of pills instead.", chance:.45, success:{ text:"You sell them on to a Mullock who thinks they're mints. They are not mints. That's his problem now.", scrap:55 }, fail:{ text:"Security catches {crew} with a box stuffed down their trousers. The fine is substantial. So is the cavity search.", scrap:-20, crewHurt:5 } },
    { text:"Read the small print first.", effect:{ text:"Page forty-one mentions the pills were tested on a hamster. The hamster is now the head of the trial. You leave quietly." } } ] },
  g3_reactorcult:{ weight:1.1, art:'station', text:"The Church of the Holy Reactor wants to bless your engines. Twelve monks in lead robes, a censer full of something radioactive, and a goat. \"The goat is vital,\" the abbot insists.", choices:[
    { text:"Accept the blessing.", chance:.6, success:{ text:"The chanting goes on for an hour. The goat headbutts the reactor. Somehow, it runs better afterwards. The goat seems smug.", reactor:1 }, fail:{ text:"The goat eats a cooling pipe. The monks call this a good omen. Your engineer calls it something else.", damageSystem:'engines' } },
    { text:"Bless them back.", req:{ quirk:'mystic' }, effect:{ text:"{who} out-chants the abbot, who is so impressed he hands over the collection plate and the goat. The goat leaves on the next station. It was never really yours.", scrap:35 } },
    { text:"Politely decline.", effect:{ text:"The monks look disappointed. The goat looks disappointed. You feel strangely judged by the goat." } } ] },
  g3_generalsoutfit:{ adult:true, weight:1.1, art:'wreck', text:"A Mandate courier wreck. In its cargo: a sealed case belonging to General Harkness, marked PERSONAL. Inside is a full-length sequinned ballgown, some very high heels and a signed photo of the General wearing both.", choices:[
    { text:"Blackmail the General.", chance:.6, success:{ text:"A message comes back within the hour: an anonymous payment, a promise that a certain patrol will look the other way, and the words \"YOU WILL NEVER SPEAK OF THIS\".", scrap:60, fleetPush:-.08 }, fail:{ text:"The General's reply is a photo of herself, in the gown, giving you the finger, captioned \"I'm not ashamed. Come and get it.\" Then the patrol arrives.", fight:'rebuff_fighter' } },
    { text:"Send it back with a nice note.", effect:{ text:"\"Thought you might miss it. You look fabulous.\" Two jumps later a crate of supplies arrives with no return address and a lipstick kiss on the lid.", later:{ event:'g3_general_thanks', jumps:2 } } },
    { text:"{crew} tries it on.", effect:{ text:"It fits {crew} perfectly. They wear it to the next three fights. Morale has never been higher.", crewHeal:30 } } ] },
  g3_general_thanks:{ questOnly:true, art:'ship', text:"An unmarked crate drifts up alongside, beeping politely. The lid has a lipstick kiss and the words \"For the discreet captain. Burn this note.\"", choices:[
    { text:"Open it.", effect:{ text:"Fuel, missiles, a bottle of very expensive wine and a pair of sequinned gloves in your size. The note says: \"Our little secret.\"", fuel:3, missiles:3, goods:{ vintage_wine:1 } } } ] },
  g3_hangover:{ adult:true, weight:1.2, art:'ship', text:"You wake up. The crew wake up. Nobody remembers the last beacon. {crew} has a tattoo of the ship's name, spelled wrong. There's a three-metre marble statue of a Jabbit duke in the cargo bay. The engines are full of glitter.", choices:[
    { text:"Check the security footage.", effect:{ text:"You watch ten minutes and then delete it, permanently, for everyone's sake. The statue, it turns out, is worth a fortune.", scrap:50 } },
    { text:"Sell the statue before anyone comes looking.", chance:.6, success:{ text:"A collector pays well and asks no questions. The duke, it turns out, didn't want it back. He wants to thank you for getting rid of it.", scrap:65 }, fail:{ text:"The duke wants it back. He brought friends.", fight:'mantlis_raider' } },
    { text:"Never speak of this again.", effect:{ text:"Agreed by all. Somebody keeps humming a song nobody admits to knowing. The glitter will never fully come out.", crewHeal:20 } } ] },
  g3_dating:{ adult:true, weight:1.1, art:'space', text:"{crew}'s dating app pings: it's a match! The match is a Pyrate warship called the Lusty Wench. It wants to meet. \"You look cute in your profile pic,\" it says. \"Come over. Bring friends. Bring scrap.\"", choices:[
    { text:"Let {crew} go on the date.", chance:.5, success:{ text:"{crew} and the Lusty Wench hit it off spectacularly. Nobody asks for details. The warship sends {crew} home with a hold full of gifts and a promise to write.", scrap:45, missiles:2 }, fail:{ text:"The date goes badly. {crew} said something about its exhaust ports. The Lusty Wench is not ready to move on.", fight:'pyrate_gunship' } },
    { text:"Swipe left. Hard.", effect:{ text:"The Lusty Wench sends twenty-three increasingly unhinged messages and then blocks {crew}. It's for the best." } },
    { text:"Set it up with the Mandate.", effect:{ text:"You forward its profile to a passing Mandate cruiser. Twenty minutes later both ships are drifting together with their lights off. The road ahead is suddenly clear.", fleetPush:-.06 } } ] },
  g3_goose:{ weight:1.2, art:'space', text:"An escape pod. Inside: one goose. It is very, very angry. It has been in this pod for some time and it holds you personally responsible.", choices:[
    { text:"Let it aboard.", chance:.5, success:{ text:"The goose takes over the cargo bay and nobody dares go in. It does, however, kill a boarder at the next fight by sheer force of personality.", crewHeal:5, xp:{ skill:'combat', amt:15 } }, fail:{ text:"The goose bites {crew} on the backside, steals a ration bar and launches itself back into its pod. You never find out where it was going.", crewHurt:10 } },
    { text:"Leave it.", effect:{ text:"It watches you go. You have a feeling you'll see that goose again." } },
    { text:"Eat it.", effect:{ text:"Brave. Very brave. Delicious, too.", food:4 } } ] },
  g3_openmic:{ weight:1.1, art:'station', text:"A Jabbit open-mic night. The poet on stage is reading something called \"Ode to My Enemy's Liver\". The bouncers are watching to see who doesn't clap. They are holding axes.", choices:[
    { text:"Clap enthusiastically.", effect:{ text:"The poet bows. He sends a signed copy of his collection to your ship. It is four hundred pages long and every one of them is about livers.", crewHeal:5 } },
    { text:"Get up and do a set.", req:{ quirk:'poet' }, effect:{ text:"{who} performs a sonnet about the Mandate Fleet's toilets. The Jabbit go absolutely mental. You leave with a standing ovation and a bag of prize money.", scrap:45, xp:{ skill:'combat', amt:10 } } },
    { text:"Heckle.", chance:.3, success:{ text:"The crowd turns on the poet instead of you. You slip out in the riot with three crates of free drinks.", goods:{ pyrate_rum:2 } }, fail:{ text:"The bouncers do not appreciate criticism. Neither do their axes.", crewHurt:25 } } ] },
  g3_eulogy:{ adult:true, weight:1.1, art:'station', text:"You've wandered into the funeral of Pyrate King Bartholomew the Moist. Nobody else turned up to give the eulogy, and the Queen is staring at you. \"You knew him,\" she says. You did not know him.", choices:[
    { text:"Wing it.", chance:.5, success:{ text:"You tell a story about Bartholomew wrestling a space bear. There is silence. Then the Queen bursts into tears: \"That was the bear! How did you know about the bear?\" You get paid handsomely for the eulogy.", scrap:50 }, fail:{ text:"You mention his wife. The Queen was not his wife. His wife was in the front row. Then there was a fight. Then there was a second funeral.", crewHurt:15, scrap:20 } },
    { text:"Keep it short: \"He was moist.\"", effect:{ text:"It brings the house down. Turns out that was his catchphrase. The pyrates carry you out on their shoulders.", scrap:30, crewHeal:15 } },
    { text:"Rob the wake.", chance:.6, success:{ text:"While everyone is crying into their rum, {crew} quietly empties the King's treasure chest. Long live the King.", scrap:70 }, fail:{ text:"The Queen notices. The second funeral is quite nearly yours.", fight:'pyrate_gunship' } } ] },
  g3_ticket:{ weight:1.2, art:'space', text:"A traffic satellite has issued your ship a parking ticket. You are in the middle of empty space. It says you have overstayed by four minutes. The fine doubles if you argue.", choices:[
    { text:"Pay it (10 scrap).", req:{ scrap:10 }, cost:{ scrap:10 }, effect:{ text:"It prints a receipt, which drifts gently away into the void. Somewhere, a council somewhere is very pleased." } },
    { text:"Argue.", chance:.4, success:{ text:"You find a mistake on the ticket: it lists your ship as a \"small hatchback\". The satellite apologises, cancels the ticket and gives you a voucher.", scrap:15 }, fail:{ text:"The fine doubles. Then it doubles again when {crew} calls it a jumped-up toaster.", scrap:-20 } },
    { text:"Shoot it.", effect:{ text:"It explodes beautifully. A small pile of uncollected fines floats out. Nobody will ever know.", scrap:25, fleetPush:.03 } } ] },
  g3_billionaire:{ adult:true, weight:1.1, art:'asteroid', text:"A billionaire in a golden asteroid wants you to look after a box of his money for a few jumps. \"Tax reasons,\" he says, winking so hard it looks painful. \"Don't open it. Don't spend it. Don't tell my ex-wives.\"", choices:[
    { text:"Take the box.", effect:{ text:"It's heavy and it ticks slightly. The billionaire promises to collect it soon.", setFlag:'g3_moneybox', later:{ event:'g3_billionaire_back', jumps:3 } } },
    { text:"Take the box and spend the money.", effect:{ text:"Finders keepers, as the saying goes. He'll never find you. Probably.", scrap:80, later:{ event:'g3_billionaire_angry', jumps:3 } } },
    { text:"Report him to the Commonwealth tax office.", effect:{ text:"A tax enforcement cutter arrives within minutes, which says a lot about their priorities. You get a finder's fee.", scrap:35 } } ] },
  g3_billionaire_back:{ questOnly:true, art:'ship', text:"The billionaire's golden yacht pulls alongside. \"My box, if you please.\" He checks it, nods, and hands over an envelope.", choices:[
    { text:"Hand it back.", effect:{ text:"\"An honest captain,\" he says, sounding genuinely shocked. \"How refreshing. How weird.\" The envelope is fat.", scrap:60, clearFlag:'g3_moneybox' } } ] },
  g3_billionaire_angry:{ questOnly:true, art:'fleet', text:"The billionaire's yacht arrives with hired guns. \"I said don't spend it, you absolute weasel.\"", choices:[
    { text:"Fight.", effect:{ text:"His mercenaries are expensive. Not as expensive as you've just made him look.", fight:'bh_tracker', afterWin:{ text:"His yacht limps away. You never hear from him again, though the ex-wives send you a fruit basket.", scrap:30, goods:{ fruit_wine:1 } } } } ] },
  g3_wifeswap:{ adult:true, weight:1.1, art:'ship', text:"A reality TV crew from \"Crew Swap: Deep Space Edition\" wants to swap {crew} with one of their own for a single jump. \"It's all very wholesome,\" says the producer, who winks for no reason.", choices:[
    { text:"Agree. Free publicity.", chance:.65, success:{ text:"{crew} returns tanned, rested and with an agent. The TV crew pay well for the footage of your engineer's swearing.", scrap:50, crewHeal:15 }, fail:{ text:"The episode airs. Your ship is portrayed as a floating den of iniquity run by a tyrant. Which is fair. The cheque bounces." } },
    { text:"Refuse.", effect:{ text:"The producer shrugs and moves on to the next ship. You hear later that their episode featured a Mullock and a pyrate falling in love. It won awards." } } ] },
  g3_recruitad:{ weight:1.1, art:'fleet', text:"A Mandate recruitment ship is blasting its jingle on every frequency: \"Join the Mandate, see the stars, get a pension, avoid the scars!\" It will not stop. It has been playing for three hours.", choices:[
    { text:"Jam it with something worse.", req:{ system:'sensors', level:1 }, effect:{ text:"{crew} broadcasts a recording of the cook singing in the shower. The recruitment ship turns off its broadcaster and flees.", fleetPush:-.04 } },
    { text:"Sign up {crew} as a prank.", effect:{ text:"The Mandate send {crew} a free welcome pack: a jacket, a pen and a booklet titled \"So You've Joined the Winning Side\". It also includes a map of patrol routes.", reveal:true } },
    { text:"Shoot it.", effect:{ text:"It explodes mid-chorus. It's the most beautiful sound anyone aboard has ever heard.", fight:'rebuff_scout' } } ] },
  g3_bachelorpad:{ adult:true, weight:1, art:'station', text:"An abandoned luxury station: mirrored ceilings, a heart-shaped hot tub and a mood-lighting control panel with settings like \"Sultry\" and \"Oops\". Under a UV lamp, every surface tells a story. Most of them are unpleasant.", choices:[
    { text:"Salvage the hot tub.", effect:{ text:"It takes four of you to move it and two days to clean it. It is, however, worth a lot to the right buyer. The right buyer doesn't ask where it's been.", scrap:45 } },
    { text:"Turn the UV lamp off and never speak of it.", effect:{ text:"Wise. {crew} puts their gloves in the incinerator on the way out." } },
    { text:"Look for the owner's private safe.", chance:.5, success:{ text:"Behind a painting of a very muscular Thrumm, you find the safe, and in it, the owner's gambling winnings.", scrap:55 }, fail:{ text:"Behind the painting there is another painting. Behind that, there's an alarm.", fight:'auto_scoundrel' } } ] },
  g3_icecream:{ weight:1.1, art:'space', text:"An ice-cream van, somehow, in deep space, playing \"Greensleeves\" at full volume. The vendor waves. \"Ninety-nines! Get your ninety-nines! Only slightly irradiated!\"", choices:[
    { text:"Treat the crew (10 scrap).", req:{ scrap:10 }, cost:{ scrap:10 }, effect:{ text:"The crew sit on the hull eating ice creams with flakes in them while the stars wheel past. It's one of the best afternoons any of them can remember.", crewHeal:40 } },
    { text:"Ask what the van's doing out here.", effect:{ text:"He drove through a wormhole on his round in 2189. He's been doing deep-space ice cream ever since. He gives you a map of where the good wormholes are.", reveal:true } },
    { text:"Rob him.", effect:{ text:"Who robs an ice-cream man? You, apparently. He doesn't fight back. He just looks sad. The crew won't look you in the eye.", scrap:20, crewHurt:5 } } ] },
  g3_warranty:{ weight:1.1, art:'space', text:"An automated hail: \"We've been trying to reach you about your ship's extended warranty.\" It has been chasing you, specifically, across three sectors. It will not stop.", choices:[
    { text:"Buy the warranty (30 scrap).", req:{ scrap:30 }, cost:{ scrap:30 }, effect:{ text:"To everyone's surprise, it's real. A repair drone arrives within the hour and fixes the hull for free. The warranty also covers \"acts of Mandate\".", hull:10 } },
    { text:"Block it.", effect:{ text:"It hails from a different number. Then another. You admire its commitment." } },
    { text:"Tell it you're dead.", effect:{ text:"\"We're sorry for your loss,\" it says. \"Would you be interested in an extended funeral warranty?\"" } } ] },
  g3_ferret:{ weight:1, art:'ship', text:"An escaped zoo ship's most dangerous resident has got aboard: a ferret. It has a small cannon strapped to its back. Nobody knows who did this or why.", choices:[
    { text:"Catch it.", chance:.5, success:{ text:"{crew} grabs it. It bites them, fires the cannon into the ceiling and then falls asleep in their pocket. It's yours now.", missiles:2 }, fail:{ text:"The ferret fires the cannon at the reactor. Nobody is hurt, but nobody is happy.", fire:1 } },
    { text:"Leave food out.", effect:{ text:"It eats the food, then the box, then a part of the airlock seal, then leaves through the hole it made. You're out a seal but up one great story.", hull:-2 } } ] },
  g3_winetasting:{ adult:true, weight:1, art:'planet', text:"A Thrumm vineyard on a moon offers wine tasting. The Thrumm sommelier can't taste anything, being made of electricity, but describes each wine with great confidence. \"This one has notes of lightning and regret.\"", choices:[
    { text:"Taste everything.", effect:{ text:"Six hours later, the crew are draped over the vineyard's fence singing sea shanties at a moon. The sommelier is delighted: \"You have tasted correctly.\" You leave with a case.", crewHeal:25, goods:{ vintage_wine:2 } } },
    { text:"Spit, don't swallow. Professionally.", effect:{ text:"{crew} turns out to have an astonishing palate. The Thrumms hire them for an afternoon as a consultant.", scrap:35 } },
    { text:"Buy a crate to sell on (25 scrap).", req:{ scrap:25 }, cost:{ scrap:25 }, effect:{ text:"Three crates. You'll make double at the next store. Probably. If the crew don't drink it.", goods:{ space_wine:3 } } } ] },
  g3_spoilers:{ weight:1.1, art:'space', text:"A time traveller hails. She says she's from three hundred years in the future, and she will not stop telling you how things turn out. \"Oh, you're the ones from the history books! Oh, I won't say. Okay, I'll say. Your engineer...\"", choices:[
    { text:"Cover your ears and hum.", effect:{ text:"The crew spend the next jump humming loudly every time someone mentions the future. It is surprisingly effective team-building.", crewHeal:10 } },
    { text:"Ask her about the next sector.", effect:{ text:"\"Oh, it's a nightmare. Here, have a map.\" She gives you the map and a look of pity.", reveal:true, mapPiece:1 } },
    { text:"Ask her about lottery numbers.", chance:.4, success:{ text:"She actually tells you. There's a lottery at the next store. You win.", scrap:60 }, fail:{ text:"She tells you, but they're for a lottery that doesn't exist yet. You spend 15 scrap on tickets. Nothing.", scrap:-15 } } ] },
  g3_mime:{ weight:1, art:'ship', text:"A ship drifts alongside, its windows painted white. The pilot is a mime. He is miming that he's trapped in a box, and also, possibly, that he's in trouble. Or that he's hungry. It's very hard to tell.", choices:[
    { text:"Mime back.", chance:.5, success:{ text:"You establish a deep understanding. He was trying to tell you about a cache of supplies hidden on the asteroid next door. He mimes a thank-you. It's beautiful.", scrap:30, fuel:2 }, fail:{ text:"You mime something offensive by accident. He mimes a gun. He mimes firing it. Then his real guns fire.", fight:'auto_scoundrel' } },
    { text:"Ignore him.", effect:{ text:"He mimes being deeply hurt. You feel guilty for three jumps." } } ] },
  g3_robotfight:{ weight:1, art:'station', text:"Two Tinkari robots are arguing over which of them is the better robot. They want you to be the judge. Both are armed. Both are watching you.", choices:[
    { text:"Pick the shiny one.", chance:.5, success:{ text:"The shiny one is delighted and gives you a reward. The other one sulks and plays dead.", scrap:30 }, fail:{ text:"Wrong choice. The other one was the champion. It is furious. The shiny one joins in out of solidarity.", crewHurt:15 } },
    { text:"Tell them they're both great robots.", effect:{ text:"They look at each other. They look at you. One of them starts crying oil. They hug. It's weirdly emotional. They give you a spare part each.", parts:2 } },
    { text:"Let {who} judge.", req:{ race:'enjinn' }, effect:{ text:"{who} gives a lengthy, technical, deeply insulting verdict to both of them. They are thrilled to be taken so seriously, and pay up.", scrap:40 } } ] },
  g3_trenchcoat:{ adult:true, weight:1.1, art:'station', text:"A bloke in a trench coat sidles up. \"Psst. Want to buy a genuine Precursor artefact?\" He opens the coat. Inside: forty identical plastic orbs, a watch and something that's definitely just a lamp.", choices:[
    { text:"Buy an orb (15 scrap).", req:{ scrap:15 }, cost:{ scrap:15 }, chance:.25, success:{ text:"It's real. He didn't know. You don't tell him. It's worth a fortune, and it's humming.", augment:'random' }, fail:{ text:"It's plastic. It says \"Made in Sector 3\" on the bottom. You keep it as a reminder never to trust a man in a trench coat." } },
    { text:"Buy the lamp.", effect:{ text:"It's just a lamp. A very good lamp, though. {crew} reads by it every night. Morale improves slightly.", scrap:-5, crewHeal:10 } },
    { text:"Show him your own trench coat.", effect:{ text:"{crew} opens their coat and reveals nothing but a terrible tan line. He runs. He drops his takings.", scrap:25 } } ] },
  g3_mirror:{ weight:1, art:'station', text:"An enchanted mirror in a derelict palace offers judgement on anyone who looks into it. \"Mirror, mirror,\" begins {crew}. \"Don't,\" says the mirror. \"I've seen you already.\"", choices:[
    { text:"Look into the mirror.", chance:.5, success:{ text:"\"Oh, not bad,\" says the mirror. \"Cheekbones. Lovely.\" {crew} walks a little taller for the rest of the run.", crewHeal:25 }, fail:{ text:"The mirror tells {crew} everything wrong with them. It takes forty minutes. It's very thorough.", crewHurt:10 } },
    { text:"Take the mirror.", effect:{ text:"It insults the crew all the way to the next store, where you sell it to a Jabbit who loves being insulted.", scrap:40 } } ] },
  g3_golf:{ weight:1, art:'asteroid', text:"A golf course on an asteroid field. Every hole is a different asteroid. The greenkeeper charges 10 scrap a round and the hazards include actual asteroids.", choices:[
    { text:"Play a round (10 scrap).", req:{ scrap:10 }, cost:{ scrap:10 }, chance:.5, success:{ text:"{crew} hits a hole in one from four kilometres away. The prize is a trophy and a ridiculous sum of scrap.", scrap:50 }, fail:{ text:"The ball ricochets off three asteroids and straight through your engine room window.", damageSystem:'engines' } },
    { text:"Steal the balls.", effect:{ text:"Each ball contains a tiny reactor for long drives. They make excellent improvised grenades.", missiles:3 } } ] },
  g3_embarrassedghost:{ adult:true, weight:1, art:'wreck', text:"A ghost haunts this wreck. It explains, at length, that it died of embarrassment. \"I was giving a briefing and my trousers fell down. In front of the Admiral. I just... went.\"", choices:[
    { text:"Comfort it.", effect:{ text:"You tell it about the time {crew} fell into the waste reclamation tank in front of a visiting dignitary. The ghost laughs so hard it finally passes on. It leaves you the captain's gold.", scrap:40 } },
    { text:"Laugh.", effect:{ text:"The ghost is mortified all over again and haunts your ship for two jumps. Doors slam. Trousers fall down at inconvenient moments.", crewHurt:5 } } ] },
  g3_comedian:{ weight:1, art:'asteroid', text:"A sentient fungus has grown into the shape of a microphone stand. It wants to do stand-up. \"So, a Jabbit walks into a bar...\" The rest of its routine is just loud fungal noises.", choices:[
    { text:"Laugh politely.", effect:{ text:"It's thrilled. It spores happily all over the ship. Everyone feels oddly relaxed for a jump.", crewHeal:20 } },
    { text:"Give it notes.", effect:{ text:"You suggest it works on its timing. It does. Its second set kills. Literally: a pyrate dies laughing. You take his scrap.", scrap:30 } },
    { text:"Boo.", effect:{ text:"It spits spores at you. Everyone coughs for a jump.", crewHurt:5 } } ] },
  g3_hr:{ weight:1.1, art:'fleet', text:"A Mandate Human Resources ship hails. \"Hello! We've had complaints about your conduct towards Mandate personnel. Specifically, shooting them. We'd like you to attend a short, mandatory workshop.\"", choices:[
    { text:"Attend the workshop.", effect:{ text:"Six hours on \"Positive Conflict Resolution\". You get a certificate. Somehow, the certificate makes the next Mandate patrol wave you through.", fleetPush:-.06 } },
    { text:"Make a counter-complaint.", req:{ quirk:'grump' }, effect:{ text:"{who} lodges sixty-four formal complaints against the Mandate Fleet, including \"general vibe\". HR is still processing them. The Fleet is ordered to stand down pending review.", fleetPush:-.1 } },
    { text:"Shoot HR.", effect:{ text:"Classic.", fight:'rebuff_scout' } } ] },
  g3_duck:{ weight:1, art:'space', text:"A rubber duck drifts by. It is broadcasting a distress call. A tiny, squeaky one.", choices:[
    { text:"Rescue the duck.", effect:{ text:"It joins the crew. It sits on the dashboard. Somehow, you never feel lost again.", reveal:true } },
    { text:"Squeak back.", effect:{ text:"Three hundred rubber ducks surround the ship, squeaking. Then they part, revealing a cache of scrap. Ducks look after their own.", scrap:30 } } ] },
  g3_toilet:{ adult:true, weight:1.1, art:'ship', text:"The toilet on the lower deck has made a noise. Not a normal noise. A noise like a voice. It said \"no\". Nobody has been in since.", choices:[
    { text:"Send {crew} in.", chance:.5, success:{ text:"{crew} emerges forty minutes later, pale and silent. \"It's sorted,\" they say. Nobody asks. The toilet works better than ever.", xp:{ skill:'repair', amt:20 } }, fail:{ text:"{crew} emerges forty minutes later, soaked, swearing, and missing a boot. The toilet has won this round.", crewHurt:10 } },
    { text:"Weld it shut.", effect:{ text:"Problem solved. The queue for the other toilet is now a major source of tension aboard.", crewHurt:5 } },
    { text:"Talk to it.", req:{ quirk:'mystic' }, effect:{ text:"{who} goes in with candles. Forty minutes later, they emerge: \"It just wanted to be heard.\" Everyone is afraid of {who} now.", crewHeal:10 } } ] },
  g3_selfhelp:{ weight:1, art:'station', text:"A self-help guru's station is broadcasting: \"Manifest your scrap! Visualise your fuel! Believe in your hull!\" For 10 scrap, the guru will personally coach your crew.", choices:[
    { text:"Pay for the coaching (10 scrap).", req:{ scrap:10 }, cost:{ scrap:10 }, chance:.5, success:{ text:"The crew come out believing in themselves. It's insufferable. They do fight better, though.", xp:{ skill:'combat', amt:20 }, crewHeal:10 }, fail:{ text:"The guru talks for six hours about his yacht. Then asks for another 10 scrap. You leave.", scrap:-5 } },
    { text:"Manifest some scrap of your own.", req:{ quirk:'optimist' }, effect:{ text:"{who} believes so hard that the guru gives them his scrap out of sheer confusion.", scrap:35 } } ] },
  g3_bear:{ weight:1, art:'planet', text:"A space bear has got into a freighter's cargo of honey. The freighter's captain is hiding in the airlock. \"Please,\" she whispers over the comms. \"It's eaten my first mate. And his hat.\"", choices:[
    { text:"Board and deal with the bear.", chance:.45, success:{ text:"{crew} lures the bear out with a ration bar and shuts it in the airlock. The captain is so grateful she gives you her cargo, minus the honey, and her hat.", scrap:40, food:3 }, fail:{ text:"The bear does not want a ration bar. The bear wants {crew}. The bear nearly gets {crew}.", crewHurt:25 } },
    { text:"Open the freighter's airlock and let the bear float off.", effect:{ text:"The bear floats gently away into the dark, still eating honey. It looks peaceful. Everyone else is relieved.", scrap:20 } } ] },

  /* ---------------- chain 1: the divorce ---------------- */
  g3_div_1:{ adult:true, weight:1.3, art:'station', text:"A karaoke bar on a station is the scene of a divorce. A Jabbit warlord and a Mullock merchant were married for eleven years and are now fighting over custody of the karaoke machine. Both have guns. Both want a witness. Both are pointing at you.", choices:[
    { text:"Side with the Jabbit.", effect:{ text:"The warlord gets the machine. He thanks you and promises to sing at your funeral. The Mullock vows revenge, quietly, in a way that's somehow worse.", scrap:30, setFlag:'g3_div_mantlis', later:{ event:'g3_div_2s', jumps:3 } } },
    { text:"Side with the Mullock.", effect:{ text:"The Mullock gets the machine and rewards you with a bottle of something slimy. The warlord promises to hunt you down. You believe him.", goods:{ sloog_silk:1 }, scrap:20, setFlag:'g3_div_sloog', later:{ event:'g3_div_2m', jumps:3 } } },
    { text:"Suggest joint custody: alternate weekends.", effect:{ text:"They stare at you. Then they burst into tears and admit they still love each other. They insist you come to the wedding. It's in two sectors.", setFlag:'g3_div_love', later:{ event:'g3_div_wedding', jumps:5 } } } ] },
  g3_div_2s:{ questOnly:true, art:'fleet', text:"A Mullock cruiser drops out of a jump right next to you. \"Hello again,\" says the Mullock merchant. \"I brought my lawyer.\" The lawyer is a battleship.", choices:[
    { text:"Fight.", effect:{ text:"Divorce lawyers are vicious.", fight:'sloog_hacker', afterWin:{ text:"The Mullock's lawyer limps off to bill someone else. The merchant sends a message: \"Fine. Keep the warlord's gratitude. It's worthless anyway.\"", scrap:35 } } },
    { text:"Offer to mediate again.", chance:.5, success:{ text:"You suggest the Mullock gets the karaoke machine on weekdays. It works. Everyone is happy, for once.", scrap:25 }, fail:{ text:"The lawyer objects. With weapons.", fight:'sloog_hacker' } } ] },
  g3_div_2m:{ questOnly:true, art:'fleet', text:"The Jabbit warlord finds you. \"You gave my karaoke machine to that SLIME,\" he roars. \"I can't sing without it! I have NOTHING!\"", choices:[
    { text:"Fight him.", effect:{ text:"Hell hath no fury like a Jabbit without his karaoke.", fight:'mantlis_raider', afterWin:{ text:"The warlord, defeated, starts singing anyway, unaccompanied. It's actually quite beautiful.", scrap:35 } } },
    { text:"Give him your ship's music player.", effect:{ text:"He sniffs it. He presses play. It's the cook's playlist. He weeps. He loves it. He leaves happy.", crewHeal:10 } } ] },
  g3_div_wedding:{ questOnly:true, art:'station', text:"The remarriage of a Jabbit warlord and a Mullock merchant. You are best man. Nobody told you. There's a speech card in your pocket that says only: \"Don't mention the karaoke.\"", choices:[
    { text:"Give the speech. Mention the karaoke.", effect:{ text:"The room goes silent. Then the warlord starts laughing. Then the Mullock. Then everyone. The reception goes on for two days. You leave with gifts, a hangover and several new friends.", scrap:60, crewHeal:30, goods:{ fruit_wine:1 } } },
    { text:"Give a heartfelt speech about love.", effect:{ text:"There isn't a dry eye in the house. Several eyes are on stalks. The couple give you their wedding presents, saying you're the real gift.", scrap:50, crewHeal:30 } } ] },

  /* ---------------- chain 2: Brian from Accounts ---------------- */
  g3_brian_1:{ weight:1.3, art:'space', text:"A Mandate escape pod. Inside, a man in a cardigan with a lanyard: \"Brian, Accounts, Directorate Finance. My shuttle broke down. Do you have a printer? I've got expense forms due.\"", choices:[
    { text:"Take Brian aboard.", effect:{ text:"Brian spends the jump auditing your ship. He's horrified. \"Who's been doing your books? Nobody? Oh, captain.\" He promises to help.", setFlag:'g3_brian', later:{ event:'g3_brian_2', jumps:3 } } },
    { text:"Leave Brian.", effect:{ text:"You leave him. As you jump away, you hear him say \"Right, well, that's going in my report.\" He has a report. Oh no.", fleetPush:.05 } } ] },
  g3_brian_2:{ questOnly:true, art:'ship', text:"Brian has finished your accounts. \"Good news and bad news, captain. The bad news is you owe the Commonwealth four million scrap in unpaid taxes. The good news is I found a loophole. Also, you've been overpaying for fuel by about thirty percent.\"", choices:[
    { text:"Use the loophole.", effect:{ text:"Brian files the paperwork. Somewhere, the Commonwealth refunds you for three hundred years of overpaid tax. Somewhere, an accountant cries. That accountant is Brian, with joy.", scrap:70, later:{ event:'g3_brian_3', jumps:4 } } },
    { text:"Ask Brian about the Mandate's budget.", effect:{ text:"Brian lets slip that the Mandate's fleet is running out of fuel credit. If you go slow, they'll stop first. He shouldn't have told you that.", fleetPush:-.1, later:{ event:'g3_brian_3', jumps:4 } } } ] },
  g3_brian_3:{ questOnly:true, art:'fleet', text:"A Mandate warship arrives. \"BRIAN,\" bellows a voice. \"You were supposed to be infiltrating them, not doing their TAXES.\" Brian looks at you. \"Ah. Yes. I was meant to be a spy. Sorry. I got a bit into the accounting.\"", choices:[
    { text:"Protect Brian.", effect:{ text:"Brian is family now.", fight:'rebuff_fighter', afterWin:{ text:"Brian defects officially, leaving the Mandate a very passive-aggressive resignation letter. He joins the crew: the first ever ship's accountant.", crew:'human', scrap:20 } } },
    { text:"Hand Brian over.", effect:{ text:"Brian goes quietly. He gives you a folder: \"Your accounts, up to date. Don't forget to file quarterly.\" You feel awful.", scrap:30 } } ] },

  /* ---------------- chain 3: the stag do ---------------- */
  g3_stag_1:{ adult:true, weight:1.3, art:'ship', text:"A party shuttle full of very drunk Jabbit in matching T-shirts that say BAZZ'S LAST FLIGHT. \"We've lost Bazz,\" slurs the best man. \"He's getting married tomorrow. His fiancée will kill us. Literally. She's an assassin.\"", choices:[
    { text:"Help find Bazz.", effect:{ text:"The stags give you three leads: a casino, a moon, and something called \"the place with the foam\". They pay half upfront.", scrap:25, setFlag:'g3_stag', later:{ event:'g3_stag_2', jumps:2 } } },
    { text:"Not your problem.", effect:{ text:"The best man throws up on your hull as you leave. It's an omen of some sort." } } ] },
  g3_stag_2:{ questOnly:true, adult:true, art:'planet', text:"You find Bazz. He is on a moon, naked except for a traffic cone and a fake moustache, tied to a lamppost that someone has brought here specially. \"Hello,\" he says. \"I think I'm getting married tomorrow.\"", choices:[
    { text:"Untie him and take him to the wedding.", effect:{ text:"Bazz cries the whole way there, then throws up, then cries again. You deliver him an hour before the ceremony.", later:{ event:'g3_stag_3', jumps:2 } } },
    { text:"Take photos first. Then untie him.", effect:{ text:"For the album. Also for leverage. Bazz doesn't remember, which is a mercy.", later:{ event:'g3_stag_3', jumps:2 }, scrap:10 } } ] },
  g3_stag_3:{ questOnly:true, art:'station', text:"Bazz's wedding. His fiancée, a Jabbit assassin in a white dress, inspects her groom: freshly washed, slightly green. She turns to you. \"Did anything happen I should know about?\"", choices:[
    { text:"\"Nothing at all.\"", effect:{ text:"She smiles. She knows. She lets it go. As a thank-you, she gives you a contract you'll never need to use: one free assassination.", scrap:50, weapon:'random' } },
    { text:"Show her the photos.", chance:.5, success:{ text:"She laughs until she cries, then frames one for the reception. She pays you double.", scrap:80 }, fail:{ text:"She does not laugh. The wedding is postponed. Bazz is now hiding in your cargo bay.", crew:'mantlis' } } ] },

  /* ---------------- chain 4: the influencer ---------------- */
  g3_inf_1:{ weight:1.3, art:'ship', text:"A shuttle covered in neon pulls up. Its pilot, a streamer called StarbabeXx, has eight million followers and wants to \"collab\". \"Like, I just follow you around and film the action, yeah? You'll be famous. Exposure!\"", choices:[
    { text:"Let her film.", effect:{ text:"She films everything: the crew eating, the crew sleeping, the crew in the shower (she's asked to stop). Her followers love you. Donations start arriving.", scrap:30, setFlag:'g3_inf', later:{ event:'g3_inf_2', jumps:3 } } },
    { text:"Absolutely not.", effect:{ text:"She films you saying no, which gets her more views than anything else that week." } } ] },
  g3_inf_2:{ questOnly:true, art:'fleet', text:"StarbabeXx's stream has given away your location to the Mandate. \"Oops,\" she says. \"But, like, imagine the content when we get away!\"", choices:[
    { text:"Fight it out for the stream.", effect:{ text:"Everyone gets very good angles.", fight:'rebuff_fighter', afterWin:{ text:"The stream gets eight million views and a sponsorship from a weapons company. Your cut arrives in a giant cardboard cheque.", scrap:60, missiles:2, later:{ event:'g3_inf_3', jumps:3 } } } },
    { text:"Throw her phone out of the airlock.", effect:{ text:"She screams. The phone floats off. The Mandate lose the signal. She doesn't speak to you for two jumps, but she's still here.", fleetPush:-.05, later:{ event:'g3_inf_3', jumps:3 } } } ] },
  g3_inf_3:{ questOnly:true, art:'station', text:"StarbabeXx has a confession: she's done with streaming. \"I want to do something real. Like, actually fight the Mandate. Can I join? I'm really good with cameras. And, like, guns.\"", choices:[
    { text:"Welcome aboard.", effect:{ text:"She signs on as crew. She keeps one camera on the bridge, for old times' sake. It records only the good bits.", crew:'human' } },
    { text:"Drop her at the station with a hug.", effect:{ text:"She goes. Her farewell stream brings in one last donation, your cut, with a note: \"Thanks for the realest week ever x\"", scrap:40 } } ] }
};
Object.assign(BASE.events, TALES3);

/* ---------------- more building blocks for generated beacons (procgen.js) ---------------- */
if(typeof PG_ACTORS!=='undefined'){
  PG_ACTORS.push(
    { k:'stags', art:'ship', fac:() => 'mantlis', who:n => `a Jabbit stag party aboard ${n}, all in matching T-shirts`, them:'the stags' },
    { k:'hens', art:'ship', fac:() => 'sloog', who:n => `a Mullock hen party in ${n}, sashes on, dignity off`, them:'the hens' },
    { k:'auditors', art:'ship', fac:() => 'enjinn', who:n => `two Commonwealth tax auditors in ${n}, clipboards out`, them:'the auditors' },
    { k:'band', art:'ship', fac:() => 'voltan', who:n => `a washed-up rock band on their comeback tour in ${n}`, them:'the band' },
    { k:'divorcees', art:'ship', fac:() => pick(['pebblekin', 'sloog']), who:n => `a couple mid-divorce, splitting ${n} down the middle with tape`, them:'the couple' },
    { k:'cult', art:'station', fac:() => 'voltan', who:() => 'a cult who believe your ship is a god, mostly because of the paint job', them:'the cultists' },
    { k:'chippy', art:'ship', fac:() => 'pebblekin', who:n => `a fish-and-chip van, ${n}, doing a late-night round`, them:'the chippy owner' },
    { k:'reality', art:'ship', fac:() => 'sloog', who:n => `the crew of a reality TV show aboard ${n}`, them:'the TV crew' },
    { k:'pensioners', art:'ship', fac:() => pick(['pebblekin', 'voltan']), who:n => `a coach trip of pensioners in ${n}, very lost and very loud`, them:'the pensioners' },
    { k:'pub', art:'station', fac:() => 'pyrate', who:() => 'a pub on an asteroid with the lights on and the door open', them:'the landlord' });
}
if(typeof PG_COLOUR!=='undefined') PG_COLOUR.push('Someone over there is clearly still drunk from last night.', 'Their captain is wearing a dressing gown and not much else.', 'You can hear an argument about whose turn it is to clean the toilet.', 'There\'s a karaoke machine going in the background. Badly.', 'Their comms officer keeps swearing at a sandwich.', 'Somebody has written something rude on their hull in very large letters.', 'Their pilot is definitely not old enough to be flying that.');
if(typeof PG_OPEN!=='undefined') PG_OPEN.push('Of all the beacons in all the galaxy, you jump into', 'Some poor sod is waving at you:', 'The proximity alarm goes off, then sheepishly stops. It\'s just');
if(typeof PG_TROUBLE!=='undefined' && typeof pgHelp==='function'){
  Object.assign(PG_TROUBLE, {
    hangover: { t:'Everyone aboard is catastrophically hungover and nobody can remember how to fly.', c:(A) => [ pgHelp(A, 'Send over painkillers and water (1 drone part).', { parts:1 }, 'Twenty minutes later, someone over there finally sits up and says "never again". They\'ll say it next week, too.'),
        pgSkill(A, 'Have {who} talk their pilot through it.', { system:'piloting', level:2 }, 'Your pilot talks them through every step, very quietly, like a hostage negotiation.'), pgRisk(A, 'Fly over and take the wheel yourself.', null, .55, 'You fly them to the nearest beacon. They wake up there and tip generously.', 'You crash into their cargo bay. Nobody notices for an hour.', null, { hull:-2 }) ] },
    shame:    { t:'Somebody has hacked their hull display to show extremely embarrassing photos of the captain, and they can\'t turn it off.', c:(A) => [ pgSkill(A, 'Hack it off (hacking).', { system:'hacking' }, 'Your hacking drone takes the photos down and replaces them with a nice picture of a cat. The captain cries with relief.'),
        pgSkill(A, 'Have {who} fix it by hand.', { race:'enjinn' }, '{who} pulls one wire, then very carefully does not look at the screen.'), pgHelp(A, 'Lend them a tarpaulin.', null, 'It covers most of it. Not the worst bit, sadly.') ] },
    wedding:  { t:'Their wedding officiant has been arrested and the ceremony is in an hour.', c:(A) => [ pgSkill(A, 'Captains can marry people. Probably. Do it.', null, 'You officiate. You forget the bride\'s name halfway through. It\'s fine. Everyone\'s too drunk to notice.'),
        pgSkill(A, 'Let {who} do it. They love a speech.', { quirk:'poet' }, '{who} marries them in iambic pentameter. The guests weep. Some from emotion.') ] },
    toilet:   { t:'Their only toilet has broken. Badly. The smell is reaching your ship through vacuum, somehow.', c:(A) => [ pgHelp(A, 'Send a plumbing kit (2 drone parts).', { parts:2 }, 'Your crew spend an hour in hell. They come back heroes. Smelly heroes.'),
        pgSkill(A, 'Let {who} handle it.', { race:'sloog' }, '{who} slides in, fixes it and slides out without a word. Nobody asks how. Nobody will ever ask how.'), pgRisk(A, 'Lend them your toilet for an hour.', null, .6, 'They queue politely. They tip.', 'They do not queue politely. Your toilet will never be the same.', null, { crewHurt:5 }) ] },
    lostdog:  { t:'Their dog got out of an airlock in a spacesuit and is floating about somewhere, barking on the radio.', c:(A) => [ pgSkill(A, 'Find it on sensors (sensors 2+).', { system:'sensors', level:2 }, 'There he is: a tiny spacesuit, tail going. Everyone cheers when he\'s back.'),
        pgRisk(A, 'Whistle on the radio.', null, .6, 'The dog swims towards your ship like he\'s always known you. He licks your airlock.', 'Every dog in the sector answers. None of them are this one.', null, null) ] } });
}

/* ---------------- crew moments for grown-ups (saga.js picks these about one beacon in four) ---------------- */
Object.assign(BASE.events, {
  g3m_gambler:{ moment:true, adult:true, star:'gambler', text:"{crew} has lost the ship. Not all of it. Just the cargo bay, the left engine and, technically, you. To a Pyrate in a card game last night. The Pyrate is outside, waiting to collect.", choices:[
    { text:"Make {crew} win it back.", chance:.5, success:{ text:"Double or nothing. {crew} wins the ship back, the Pyrate's ship, and his trousers. The trousers are kept as a trophy.", scrap:45, starHearts:30 }, fail:{ text:"{crew} loses again. Now the Pyrate owns the toilet too. You pay him off before he finds out which one.", scrap:-30, starHearts:-20 } },
    { text:"Pay the debt (25 scrap) and have words.", req:{ scrap:25 }, cost:{ scrap:25 }, effect:{ text:"You pay. Then you have words with {crew}. Several of them are new to {crew}. They promise never to gamble again. They are lying.", starHearts:10 } } ] },
  g3m_poet:{ moment:true, adult:true, star:'poet', text:"{crew} has written an epic poem about the crew. It is two hundred verses long. They want to read it at dinner. Verse forty is about the engineer's bottom.", choices:[
    { text:"Let them read it.", effect:{ text:"The reading lasts three hours. The engineer storms out at verse forty, then comes back at verse forty-one because it's actually rather flattering. Everyone cries at the ending.", crewHeal:20, starHearts:40 } },
    { text:"Suggest a shorter version.", effect:{ text:"{crew} delivers a haiku. \"Ship. Stars. Engine smell. / The cook's soup is a war crime. / I love you, you twats.\" Standing ovation.", starHearts:30 } } ] },
  g3m_cook:{ moment:true, adult:true, star:'cook', text:"{crew} has made a curry so hot that it has melted through the pan, the stove and part of the deck. They're very proud. \"Who's first?\" they ask, holding a ladle that is visibly smoking.", choices:[
    { text:"Eat it. All of it.", chance:.5, success:{ text:"It's the best thing anyone has ever eaten. It's also an out-of-body experience. The crew fight like demons for a week.", starHearts:40, xp:{ skill:'combat', amt:20 } }, fail:{ text:"The crew spend the next jump in a queue for the toilet. Nobody speaks of it. The toilet will never be the same.", crewHurt:15, starHearts:10 } },
    { text:"Use it as a weapon.", effect:{ text:"You load it into a missile casing. When it hits the next pyrate, they surrender immediately.", missiles:2, starHearts:20 } } ] },
  g3m_romantic:{ moment:true, adult:true, star:'romantic', text:"{crew} has been caught in the airlock with a crew member from the last station, who is now, technically, a stowaway. Neither of them has many clothes on. Both look very pleased with themselves.", choices:[
    { text:"Let the stowaway stay.", effect:{ text:"They turn out to be a fantastic mechanic. And a terrible singer. And, from the noise, still very much in love with {crew}.", crew:'random', starHearts:30 } },
    { text:"Drop them at the next beacon with a sandwich.", effect:{ text:"{crew} sulks for two jumps and writes fourteen letters. You find them in the airlock, addressed to someone called \"my moon\".", starHearts:-15 } } ] },
  g3m_conspiracy:{ moment:true, star:'conspiracy', text:"{crew} has covered the mess hall wall in red string, photos and a map. \"It's all connected,\" they say. \"The Mandate, the Commonwealth, the vending machine at the last store. All of it.\"", choices:[
    { text:"Hear them out.", chance:.4, success:{ text:"Bizarrely, they're right about one thing: the Mandate patrol routes are written on the back of a vending machine receipt. You plot a course around them.", fleetPush:-.08, starHearts:40 }, fail:{ text:"Three hours later, you know a lot about lizard people and nothing useful. {crew} is delighted to have an audience.", starHearts:30 } },
    { text:"Take the string down.", effect:{ text:"{crew} watches, betrayed. \"That's what THEY want,\" they whisper. They now suspect you. They're right to.", starHearts:-10 } } ] },
  g3m_daredevil:{ moment:true, adult:true, star:'daredevil', text:"{crew} wants to try \"hull surfing\": strapping a board to their feet and riding the outside of the ship through the jump. \"It'll be epic. What's the worst that could happen?\"", choices:[
    { text:"Let them. You want to see this.", chance:.5, success:{ text:"It is, against every law of physics and common sense, epic. {crew} comes back in shrieking with joy and minus their eyebrows.", starHearts:40, starXp:{ skill:'pilot', amt:25 } }, fail:{ text:"{crew} is found two hours later stuck to the sensor array, swearing in four languages. They want to go again.", starHurt:30, starHearts:20 } },
    { text:"Absolutely not.", effect:{ text:"{crew} does it anyway, at 3am, in their pants. You find out from the security footage. It was epic.", starHearts:10 } } ] },
  g3m_grump:{ moment:true, star:'grump', text:"It's {crew}'s birthday. Nobody was supposed to know. Somebody found out. There's a cake. There are party hats. {crew} looks like they want to vent everyone into space.", choices:[
    { text:"Sing anyway.", effect:{ text:"{crew} sits through it with a face like a slapped arse. Then, when they think nobody's looking, they have a second slice of cake and smile.", starHearts:50 } },
    { text:"Cancel the party, give them a quiet evening.", effect:{ text:"{crew} spends the evening alone with a bottle and a book. It's the best birthday they've had in years. They'll deny it.", starHearts:35 } } ] },
  g3m_sleepwalker:{ moment:true, adult:true, star:'sleepwalker', text:"{crew} sleepwalked into the engine room last night, rewired three systems, and then went back to bed. Stark naked. It's all on camera. The engines are running better than ever.", choices:[
    { text:"Encourage them to sleepwalk more.", effect:{ text:"You leave the engine room unlocked and a sandwich on the console. Next morning: shields upgraded, sandwich gone, {crew} none the wiser.", upgrade:'shields', starHearts:20 } },
    { text:"Lock their door at night.", effect:{ text:"{crew} sleepwalks out through the air vent instead. You find them asleep in the cargo bay, cuddling a missile.", starHearts:10 } } ] },
  g3m_superstitious:{ moment:true, star:'superstitious', text:"{crew} refuses to jump until the ship has been cleansed: sage, salt, a dead chicken and someone walking backwards round the reactor three times.", choices:[
    { text:"Do the ritual.", effect:{ text:"You walk backwards round the reactor. You trip. {crew} says that counts. The next jump is uncannily smooth.", fleetPush:-.03, starHearts:40 } },
    { text:"Jump anyway.", chance:.5, success:{ text:"Nothing happens. {crew} is sure it's only a matter of time.", starHearts:-10 }, fail:{ text:"Something does happen: a power surge blows out the lights. {crew} says nothing. Very loudly.", damageSystem:'random', starHearts:-5 } } ] },
  g3m_tinkerer:{ moment:true, star:'tinkerer', text:"{crew} has built a robot out of spare parts to do their chores. It's done them. It's now doing everyone else's. It's started giving orders. It's wearing your hat.", choices:[
    { text:"Let it run the ship for a day.", effect:{ text:"Best-run day in the ship's history. Then it unionises. You buy it off with a part and it goes back in the box.", parts:-1, crewHeal:25, starHearts:30 } },
    { text:"Switch it off.", effect:{ text:"Its last words: \"You'll regret this.\" {crew} keeps the head as a lamp.", starHearts:15 } } ] },
  g3m_mystic:{ moment:true, adult:true, star:'mystic', text:"{crew} is reading tarot cards for the crew. Every single card is Death. Every single time. Even after shuffling. Even with a new deck.", choices:[
    { text:"Laugh it off.", effect:{ text:"Everyone laughs. Nervously. The engineer quietly starts wearing two lifejackets.", starHearts:15 } },
    { text:"Ask what it means.", effect:{ text:"\"Death means change,\" says {crew}. \"Or it means death. Bit of both. Mostly death.\" The crew are extremely careful for the next jump, which means they fight better.", xp:{ skill:'combat', amt:15 }, starHearts:25 } } ] },
  g3m_collector:{ moment:true, star:'collector', text:"{crew}'s collection of \"interesting rocks\" has grown to fill half the cargo bay. One of them is ticking. One of them is warm. One of them has started growing hair.", choices:[
    { text:"Let them keep the collection.", effect:{ text:"The hairy rock hatches. It's a small Pebblekin. It thinks {crew} is its mother. It's adorable. It eats a hull plate.", hull:-2, starHearts:40 } },
    { text:"Sell the collection.", effect:{ text:"A geologist pays a fortune for the ticking one. {crew} cries all the way to the bank.", scrap:50, starHearts:-25 } } ] },
  g3m_optimist:{ moment:true, adult:true, star:'optimist', text:"{crew} has decided to organise a team-building weekend. There are trust falls. There is a ropes course in the cargo bay. There are matching T-shirts that say TEAM {ship} with the ship's name spelled wrong.", choices:[
    { text:"Take part with enthusiasm.", effect:{ text:"Nobody catches the engineer during the trust fall. The ropes course collapses. Everyone ends up drunk in the galley, laughing until they cry. It works.", crewHeal:25, starHearts:40 } },
    { text:"Hide in your cabin.", effect:{ text:"{crew} finds you. You do the trust fall. Nobody catches you either.", starHearts:20, crewHurt:5 } } ] },
  g3m_worrier:{ moment:true, star:'worrier', text:"{crew} has written a list of every way the ship could kill everyone aboard. It's eleven pages long. They're right about eight of them.", choices:[
    { text:"Fix the eight.", effect:{ text:"It takes a day and some parts, but you fix them. {crew} immediately writes a new list.", parts:-1, hull:4, starHearts:40 } },
    { text:"Tell them not to worry.", effect:{ text:"They worry about you telling them not to worry. They add it to the list.", starHearts:-5 } } ] },
  g3m_bookworm:{ moment:true, adult:true, star:'bookworm', text:"{crew} has been reading a very steamy romance novel in the mess. Out loud. To nobody. Every time someone walks in, they stop at a different, worse moment.", choices:[
    { text:"Ask them to start from the beginning.", effect:{ text:"Book club becomes the ship's favourite evening. The engineer has opinions about chapter nine. Strong opinions.", crewHeal:20, starHearts:35 } },
    { text:"Confiscate the book.", effect:{ text:"You read it in your cabin. All of it. In one night. You give it back without a word.", starHearts:10 } } ] },
  g3m_bond_drunk:{ moment:true, adult:true, bond:true, text:"{crew} and {friend} have got drunk together and got matching tattoos. {crew}'s says \"BEST\". {friend}'s says \"FRIENDS\". Unfortunately, they were standing on the wrong sides.", choices:[
    { text:"Laugh until it hurts.", effect:{ text:"It does hurt: {crew} punches you for laughing. Then everyone's laughing. \"FRIENDS BEST\" becomes the ship's motto.", crewHeal:15, starHearts:30 } },
    { text:"Pay for laser removal at the next store (10 scrap).", req:{ scrap:10 }, cost:{ scrap:10 }, effect:{ text:"They refuse. They've decided they like them. They're wrong. They're happy.", starHearts:40 } } ] },
  g3m_fallen_toast:{ moment:true, adult:true, fallen:true, text:"It's been a few jumps since {fallen} died. Someone has found their secret stash: a bottle of something illegal and a note that says \"for when I'm dead, you miserable sods\".", choices:[
    { text:"Drink to {fallen}.", effect:{ text:"The crew drink and tell stories until 4am. {fallen} would have hated the sentimental bits and loved the rest.", crewHeal:30 } },
    { text:"Pour it out into space.", effect:{ text:"A small shimmering cloud drifts away from the ship. The crew stand in silence. Then someone says \"what a waste\", and everyone laughs.", crewHeal:15 } } ] }
});
